  "cmp.settings.db.skipped": { "en": "(skipped {projects} existing project(s), {sessions} existing session(s))", "ko": "(기존 프로젝트 {projects}개, 기존 세션 {sessions}개 건너뜀)", "zh": "（跳过 {projects} 个已存在的项目、{sessions} 个已存在的会话）" },
